const paths = {"icon-timer": "assets/icon-timer.png", "icon-score": "assets/icon-score.png", "icon-level": "assets/icon-level.png", "back-arrow": "assets/back-arrow.svg", "intro-fullscreen-icon": "assets/intro-fullscreen-icon.svg", "intro-voice-icon": "assets/intro-voice-icon.svg", "finger-click": "assets/finger-click.png", "feedback-countdown-sequence": "assets/audio/countdown-sequence.mp3", "feedback-level-up": "assets/audio/level-up.mp3", "feedback-time-up": "assets/audio/time-up.mp3", "feedback-time-out": "assets/audio/time-out.mp3", "feedback-success": "assets/audio/success.mp3", "feedback-fail": "assets/audio/fail.mp3"};
export const SHARED_ASSET_IDS={iconTimer:'icon-timer',iconScore:'icon-score',iconLevel:'icon-level',backArrow:'back-arrow',introFullscreenIcon:'intro-fullscreen-icon',introVoiceIcon:'intro-voice-icon',fingerClick:'finger-click'};
export const GAME_FEEDBACK_AUDIO_ASSET_IDS={countdownSequence:'feedback-countdown-sequence',levelUp:'feedback-level-up',timeUp:'feedback-time-up',timeOut:'feedback-time-out',success:'feedback-success',fail:'feedback-fail'};
export function getSharedAssetUrl(id){return paths[id]?new URL('../../../../'+paths[id],import.meta.url).href:'';}
export const getSharedAssetCdnUrl=getSharedAssetUrl;
export function getSharedFeedbackAudioUrl(type){return getSharedAssetUrl(GAME_FEEDBACK_AUDIO_ASSET_IDS[type]);}
export function applySharedAssetCssVariables(root=document.documentElement){for(const [key,id] of Object.entries({'record-icon':'icon-score','back-arrow':'back-arrow','intro-fullscreen-icon':'intro-fullscreen-icon','intro-voice-icon':'intro-voice-icon'}))root.style.setProperty('--sm-shared-'+key+'-image','url("'+getSharedAssetUrl(id)+'")');}
